/* ============================================================================
 *  AAA Geometry Helpers (Bevels, Fillets, Hollow Bowls, Tapered Profiles)
 * ==========================================================================*/

function safeMat(mats: any, key: string, fallback: THREE.Material): THREE.Material {
  if (mats && mats[key] instanceof THREE.Material) return mats[key];
  return fallback;
}

/**
 * Creates a rounded/beveled rectangular prism with realistic edge highlights.
 * Eliminates the raw 90° CG edge "Lego" look.
 */
function beveledBox(
  w: number, h: number, d: number,
  bevel: number,
  mat: THREE.Material,
  x = 0, y = 0, z = 0
): THREE.Mesh {
  const shape = new THREE.Shape();
  const b = Math.min(bevel, w * 0.25, h * 0.25, d * 0.25);
  const hw = Math.max(0.01, w * 0.5 - b);
  const hh = Math.max(0.01, h * 0.5 - b);

  shape.moveTo(-hw, -hh - b);
  shape.lineTo(hw, -hh - b);
  shape.quadraticCurveTo(hw + b, -hh - b, hw + b, -hh);
  shape.lineTo(hw + b, hh);
  shape.quadraticCurveTo(hw + b, hh + b, hw, hh + b);
  shape.lineTo(-hw, hh + b);
  shape.quadraticCurveTo(-hw - b, hh + b, -hw - b, hh);
  shape.lineTo(-hw - b, -hh);
  shape.quadraticCurveTo(-hw - b, -hh - b, -hw, -hh - b);

  const extrudeSettings: THREE.ExtrudeGeometryOptions = {
    depth: Math.max(0.02, d - b * 2),
    bevelEnabled: true,
    bevelSegments: 2,
    steps: 1,
    bevelSize: b,
    bevelThickness: b,
  };
  const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geo.center();
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function box(
  w: number, h: number, d: number,
  mat: THREE.Material,
  x = 0, y = 0, z = 0
): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function cyl(
  rt: number, rb: number, h: number, seg: number,
  mat: THREE.Material,
  x = 0, y = 0, z = 0
): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function shadowAll(g: THREE.Object3D): void {
  g.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (mesh.isMesh) {
      mesh.castShadow = true;
      mesh.receiveShadow = true;
    }
  });
}

/**
 * Builds a realistic heavy crawler track assembly with closed-loop track shoes,
 * drive sprocket with teeth, idler with tensioner, and flanged lower rollers.
 */
function createCrawlerTrackAssembly(
  trackWidth: number, trackHeight: number, trackLength: number,
  frameMat: THREE.Material,
  shoeMat: THREE.Material,
  rollerMat: THREE.Material,
  toothCount: number
): THREE.Group {
  const group = new THREE.Group();

  // Heavy side frame body with beveled plates
  const frame = beveledBox(trackWidth * 0.75, trackHeight * 0.65, trackLength * 0.88, 0.04, frameMat, 0, trackHeight * 0.5, 0);
  group.add(frame);

  // 45° beveled rock guard shields along top/sides
  const shieldTop = beveledBox(trackWidth * 0.95, 0.12, trackLength * 0.9, 0.02, frameMat, 0, trackHeight + 0.06, 0);
  group.add(shieldTop);

  // Front idler wheel (tensioned)
  const idlerR = trackHeight * 0.44;
  const frontZ = trackLength * 0.5 - idlerR;
  const idler = cyl(idlerR, idlerR, trackWidth * 0.85, 20, rollerMat, 0, idlerR + 0.1, frontZ);
  idler.rotation.z = Math.PI / 2;
  group.add(idler);

  // Rear drive sprocket (elevated with teeth & planetary hub)
  const sprocketR = trackHeight * 0.5;
  const rearZ = -trackLength * 0.5 + sprocketR;
  const sprocket = cyl(sprocketR, sprocketR, trackWidth * 0.85, 20, rollerMat, 0, sprocketR + 0.15, rearZ);
  sprocket.rotation.z = Math.PI / 2;
  group.add(sprocket);

  // Planetary final drive hub cap
  const hubCap = cyl(sprocketR * 0.55, sprocketR * 0.55, trackWidth * 0.98, 16, rollerMat, 0, sprocketR + 0.15, rearZ);
  hubCap.rotation.z = Math.PI / 2;
  group.add(hubCap);

  // Sprocket driving teeth
  for (let i = 0; i < toothCount; i++) {
    const a = (i / toothCount) * Math.PI * 2;
    const tz = rearZ + Math.sin(a) * (sprocketR + 0.08);
    const ty = (sprocketR + 0.15) + Math.cos(a) * (sprocketR + 0.08);
    const tooth = beveledBox(trackWidth * 0.72, 0.12, 0.16, 0.02, rollerMat, 0, ty, tz);
    tooth.rotation.x = a;
    group.add(tooth);
  }

  // 8 lower flanged track rollers on ground run
  const rollerR = trackHeight * 0.18;
  const rollerCount = 8;
  for (let i = 0; i < rollerCount; i++) {
    const rz = rearZ + 1.1 + (i / (rollerCount - 1)) * (frontZ - rearZ - 2.2);
    const roller = cyl(rollerR, rollerR, trackWidth * 0.78, 14, rollerMat, 0, rollerR + 0.1, rz);
    roller.rotation.z = Math.PI / 2;
    group.add(roller);

    // Double flanges
    const flL = cyl(rollerR * 1.25, rollerR * 1.25, 0.05, 14, rollerMat, -trackWidth * 0.32, rollerR + 0.1, rz);
    flL.rotation.z = Math.PI / 2;
    const flR = cyl(rollerR * 1.25, rollerR * 1.25, 0.05, 14, rollerMat, trackWidth * 0.32, rollerR + 0.1, rz);
    flR.rotation.z = Math.PI / 2;
    group.add(flL, flR);
  }

  // Upper support rollers with track sag
  for (let i = 0; i < 3; i++) {
    const rz = rearZ + 1.8 + i * ((frontZ - rearZ - 3.6) / 2);
    const sag = Math.sin((i / 2) * Math.PI) * 0.06;
    const supRoller = cyl(rollerR * 0.75, rollerR * 0.75, trackWidth * 0.65, 12, rollerMat, 0, trackHeight - rollerR * 0.75 - sag, rz);
    supRoller.rotation.z = Math.PI / 2;
    group.add(supRoller);
  }

  // Closed loop track shoes (discrete cast pads with center guide horns & grousers)
  // 1. Bottom ground contact run (flat on earth y=0.08)
  const groundPads = 18;
  for (let i = 0; i < groundPads; i++) {
    const rz = -trackLength * 0.42 + (i / (groundPads - 1)) * (trackLength * 0.84);
    const pad = beveledBox(trackWidth * 0.98, 0.12, 0.44, 0.02, shoeMat, 0, 0.08, rz);
    group.add(pad);
    // Center guide lug (кулак)
    group.add(beveledBox(trackWidth * 0.18, 0.16, 0.18, 0.02, rollerMat, 0, 0.22, rz));
    // Double grousers (грунтозацепы)
    group.add(beveledBox(trackWidth * 0.92, 0.06, 0.05, 0.01, rollerMat, 0, 0.01, rz - 0.12));
    group.add(beveledBox(trackWidth * 0.92, 0.06, 0.05, 0.01, rollerMat, 0, 0.01, rz + 0.12));
  }

  // 2. Front ramp climb to idler
  for (let i = 0; i < 4; i++) {
    const frac = (i + 1) / 5;
    const py = 0.1 + frac * idlerR;
    const pz = trackLength * 0.42 + frac * (idlerR * 0.8);
    const pad = beveledBox(trackWidth * 0.98, 0.12, 0.42, 0.02, shoeMat, 0, py, pz);
    pad.rotation.x = -0.45;
    group.add(pad);
  }

  // 3. Top return run
  const topPads = 16;
  for (let i = 0; i < topPads; i++) {
    const frac = i / (topPads - 1);
    const rz = trackLength * 0.38 - frac * (trackLength * 0.76);
    const sag = Math.sin(frac * Math.PI) * 0.08;
    const pad = beveledBox(trackWidth * 0.98, 0.12, 0.44, 0.02, shoeMat, 0, trackHeight + 0.1 - sag, rz);
    group.add(pad);
  }

  // 4. Rear ramp climb to sprocket
  for (let i = 0; i < 4; i++) {
    const frac = (i + 1) / 5;
    const py = 0.1 + frac * sprocketR;
    const pz = -trackLength * 0.42 - frac * (sprocketR * 0.8);
    const pad = beveledBox(trackWidth * 0.98, 0.12, 0.42, 0.02, shoeMat, 0, py, pz);
    pad.rotation.x = 0.48;
    group.add(pad);
  }

  return group;
}

/* ============================================================================
 *  1. SOVIET / CIS ЭКГ-15 HEAVY ROPE SHOVEL (670t / 15 m³)
 * ==========================================================================*/

export function createUpgradedEKG15(mats: any): ExcavatorRig {
  const root = new THREE.Group();
  root.name = 'EXCAVATOR_EKG15';

  const bodyMat = safeMat(mats, 'ekgTealPaint', new THREE.MeshStandardMaterial({ color: 0x1a6b6b, metalness: 0.45, roughness: 0.55 }));
  const darkSteel = safeMat(mats, 'belazChassisDark', new THREE.MeshStandardMaterial({ color: 0x242628, metalness: 0.8, roughness: 0.6 }));
  const hubSteel = safeMat(mats, 'wheelHubSteel', new THREE.MeshStandardMaterial({ color: 0x4a4d52, metalness: 0.85, roughness: 0.45 }));
  const bucketSteel = safeMat(mats, 'weatheredBucketSteel', new THREE.MeshStandardMaterial({ color: 0x4a433c, metalness: 0.65, roughness: 0.8 }));
  const manganese = safeMat(mats, 'manganeseToothSteel', new THREE.MeshStandardMaterial({ color: 0x222426, metalness: 0.9, roughness: 0.35 }));
  const ropeMat = safeMat(mats, 'steelWireRope', new THREE.MeshStandardMaterial({ color: 0x6e7278, metalness: 0.95, roughness: 0.3 }));
  const glassMat = safeMat(mats, 'cabGlass', safeMat(mats, 'tintedGlass', new THREE.MeshStandardMaterial({ color: 0x1e3344, metalness: 0.2, roughness: 0.08, transparent: true, opacity: 0.5 })));
  const yellowMat = safeMat(mats, 'hazardStripeMat', new THREE.MeshStandardMaterial({ color: 0xf2b705, metalness: 0.25, roughness: 0.55 }));
  const oreMat = safeMat(mats, 'orePayloadMat', new THREE.MeshStandardMaterial({ color: 0x5a4838, roughness: 0.95, metalness: 0.1 }));

  // ============================================================
  // 1. UNDERCARRIAGE
  // ============================================================
  const undercarriage = new THREE.Group();
  undercarriage.name = 'Undercarriage';

  // Ground contact shadow
  const shadowPlane = new THREE.Mesh(new THREE.PlaneGeometry(24, 28), safeMat(mats, 'contactShadowMat', new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.6 })));
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = 0.02;
  shadowPlane.renderOrder = 2;
  root.add(shadowPlane);

  // Left and Right heavy crawler track units
  const trackW = 1.35, trackH = 1.65, trackL = 9.6;
  const leftTrack = createCrawlerTrackAssembly(trackW, trackH, trackL, darkSteel, darkSteel, hubSteel, 14);
  leftTrack.position.x = -2.65;
  const rightTrack = createCrawlerTrackAssembly(trackW, trackH, trackL, darkSteel, darkSteel, hubSteel, 14);
  rightTrack.position.x = 2.65;
  undercarriage.add(leftTrack, rightTrack);

  // Center carbody cast pedestal connecting both crawlers
  const carbody = beveledBox(3.8, 1.2, 5.4, 0.08, darkSteel, 0, 1.2, 0);
  undercarriage.add(carbody);

  // Slew ring gear (roller path Ø4.5m with visible teeth)
  const slewRing = cyl(2.25, 2.25, 0.45, 36, hubSteel, 0, 1.85, 0);
  undercarriage.add(slewRing);
  for (let i = 0; i < 48; i++) {
    const a = (i / 48) * Math.PI * 2;
    const tooth = beveledBox(0.18, 0.32, 0.22, 0.02, hubSteel, Math.cos(a) * 2.32, 1.85, Math.sin(a) * 2.32);
    tooth.rotation.y = -a;
    undercarriage.add(tooth);
  }

  // Rear trailing 6kV high-voltage cable reel drum
  const cableReel = new THREE.Group();
  cableReel.position.set(0, 1.25, -5.2);
  const drumCore = cyl(0.85, 0.85, 1.6, 24, darkSteel, 0, 0, 0);
  drumCore.rotation.z = Math.PI / 2;
  cableReel.add(drumCore);
  const flangeL = cyl(1.15, 1.15, 0.1, 24, hubSteel, -0.85, 0, 0);
  flangeL.rotation.z = Math.PI / 2;
  const flangeR = cyl(1.15, 1.15, 0.1, 24, hubSteel, 0.85, 0, 0);
  flangeR.rotation.z = Math.PI / 2;
  cableReel.add(flangeL, flangeR);
  // Coiled heavy rubber 6kV cable
  for (let i = 0; i < 6; i++) {
    const coil = cyl(0.92, 0.92, 0.22, 20, darkSteel, -0.6 + i * 0.24, 0, 0);
    coil.rotation.z = Math.PI / 2;
    cableReel.add(coil);
  }
  undercarriage.add(cableReel);

  // Mobile PKVD-6kV outdoor switchbox on skids
  const switchbox = new THREE.Group();
  switchbox.position.set(2.4, 0.2, -5.0);
  const skids = beveledBox(1.5, 0.18, 2.2, 0.03, darkSteel, 0, 0.09, 0);
  const cubicle = beveledBox(1.3, 1.35, 1.8, 0.04, yellowMat, 0, 0.85, 0);
  switchbox.add(skids, cubicle);
  for (let i = -1; i <= 1; i++) {
    const postIns = cyl(0.08, 0.12, 0.42, 12, hubSteel, i * 0.42, 1.75, 0);
    switchbox.add(postIns);
  }
  undercarriage.add(switchbox);

  root.add(undercarriage);

  // ============================================================
  // 2. TURRET / REVOLVING DECK & MACHINERY HOUSE
  // ============================================================
  const turretGroup = new THREE.Group();
  turretGroup.position.set(0, 1.95, 0);
  turretGroup.name = 'TurretGroup';

  // Revolving heavy deck platform with perimeter safety railings
  const deck = beveledBox(6.6, 0.42, 8.8, 0.06, darkSteel, 0, 0.21, -0.4);
  turretGroup.add(deck);

  // Two-line safety handrails with yellow kickplates
  const makeRailing = (x: number, z: number, len: number, rotY: number) => {
    const rg = new THREE.Group();
    rg.position.set(x, 0.42, z);
    rg.rotation.y = rotY;
    rg.add(beveledBox(len, 0.08, 0.08, 0.01, yellowMat, 0, 0.95, 0));
    rg.add(beveledBox(len, 0.06, 0.06, 0.01, yellowMat, 0, 0.52, 0));
    rg.add(beveledBox(len, 0.15, 0.03, 0.01, darkSteel, 0, 0.08, 0)); // kickplate
    const posts = Math.max(2, Math.floor(len / 1.3));
    for (let i = 0; i <= posts; i++) {
      const px = -len / 2 + (i / posts) * len;
      rg.add(beveledBox(0.08, 0.95, 0.08, 0.01, yellowMat, px, 0.48, 0));
    }
    return rg;
  };
  turretGroup.add(makeRailing(3.2, -0.4, 8.2, Math.PI / 2));
  turretGroup.add(makeRailing(-3.2, -0.4, 8.2, -Math.PI / 2));
  turretGroup.add(makeRailing(0, -4.6, 6.2, Math.PI));

  // Two-story Soviet machinery house with beveled corners
  const house = beveledBox(5.8, 3.4, 6.8, 0.08, bodyMat, 0, 2.1, -0.8);
  turretGroup.add(house);

  // Ventilation louvers with dark intake mesh
  for (let i = 0; i < 7; i++) {
    const louverL = beveledBox(0.08, 0.28, 1.3, 0.02, darkSteel, -2.94, 1.2 + i * 0.42, -1.0);
    const louverR = beveledBox(0.08, 0.28, 1.3, 0.02, darkSteel, 2.94, 1.2 + i * 0.42, -1.0);
    turretGroup.add(louverL, louverR);
  }

  // Roof ventilation cupola / skylight monitor
  const roofMonitor = beveledBox(2.2, 0.55, 3.6, 0.04, darkSteel, 0, 4.05, -1.2);
  turretGroup.add(roofMonitor);

  // Overhead bridge crane cantilever beam with traveling trolley
  const craneBeam = beveledBox(0.35, 0.35, 7.8, 0.03, yellowMat, 0, 4.45, -0.8);
  const craneTrolley = beveledBox(0.7, 0.45, 0.65, 0.03, darkSteel, 0, 4.15, -3.2);
  const hoistBlock = cyl(0.18, 0.18, 0.5, 12, hubSteel, 0, 3.75, -3.2);
  turretGroup.add(craneBeam, craneTrolley, hoistBlock);

  // Massive rear counterweight ballast box
  const counterweight = beveledBox(5.2, 2.2, 1.8, 0.06, darkSteel, 0, 1.5, -5.1);
  turretGroup.add(counterweight);

  // Elevated operator cab (front-right: x = +2.2, z = +2.6)
  const cabGroup = new THREE.Group();
  cabGroup.position.set(2.1, 1.6, 2.6);
  // Cab body with 15° forward slanted front
  const cabBody = beveledBox(1.9, 2.2, 2.0, 0.05, bodyMat, 0, 1.1, 0);
  cabGroup.add(cabBody);
  // Slanted panoramic anti-glare glass (recessed in frame)
  const frontGlass = beveledBox(1.7, 1.35, 0.06, 0.01, glassMat, 0, 1.25, 0.98);
  frontGlass.rotation.x = -0.16;
  cabGroup.add(frontGlass);
  // Lower floor viewing window (for monitoring the pit bench & BelAZ spotting)
  const floorGlass = beveledBox(1.5, 0.45, 0.06, 0.01, glassMat, 0, 0.35, 0.98);
  cabGroup.add(floorGlass);
  // Side panoramic glass
  const sideGlassL = beveledBox(0.06, 1.35, 1.6, 0.01, glassMat, -0.92, 1.25, 0);
  const sideGlassR = beveledBox(0.06, 1.35, 1.6, 0.01, glassMat, 0.92, 1.25, 0);
  cabGroup.add(sideGlassL, sideGlassR);
  // Overhead FOPS heavy rock protection canopy
  const fopsCanopy = beveledBox(2.1, 0.16, 2.2, 0.03, darkSteel, 0, 2.28, 0);
  cabGroup.add(fopsCanopy);
  // Interior operator seat & twin joystick consoles
  const seat = beveledBox(0.55, 0.8, 0.55, 0.02, darkSteel, 0, 0.75, -0.2);
  const consoleL = beveledBox(0.32, 0.35, 0.65, 0.02, darkSteel, -0.55, 0.75, 0.25);
  const consoleR = beveledBox(0.32, 0.35, 0.65, 0.02, darkSteel, 0.55, 0.75, 0.25);
  cabGroup.add(seat, consoleL, consoleR);
  // Twin cab roof floodlights
  cabGroup.add(cyl(0.12, 0.12, 0.2, 12, hubSteel, -0.55, 2.45, 0.95).rotateX(Math.PI / 2));
  cabGroup.add(cyl(0.12, 0.12, 0.2, 12, hubSteel, 0.55, 2.45, 0.95).rotateX(Math.PI / 2));
  turretGroup.add(cabGroup);

  // ============================================================
  // 3. A-FRAME PYLON & GUY CABLES
  // ============================================================
  const aFramePylonGroup = new THREE.Group();
  aFramePylonGroup.position.set(0, 3.4, -1.6);
  aFramePylonGroup.name = 'AFramePylonGroup';

  // Heavy tubular A-frame legs
  const legL = cyl(0.24, 0.28, 5.2, 16, bodyMat, -1.35, 2.5, 0);
  legL.rotation.z = 0.28;
  const legR = cyl(0.24, 0.28, 5.2, 16, bodyMat, 1.35, 2.5, 0);
  legR.rotation.z = -0.28;
  aFramePylonGroup.add(legL, legR);
  // Tubular cross-ties
  const tie1 = cyl(0.14, 0.14, 2.2, 12, darkSteel, 0, 2.0, 0).rotateZ(Math.PI / 2);
  const tie2 = cyl(0.14, 0.14, 1.5, 12, darkSteel, 0, 3.6, 0).rotateZ(Math.PI / 2);
  aFramePylonGroup.add(tie1, tie2);
  // Apex head with heavy sheaves
  const apexHead = beveledBox(1.2, 0.5, 0.8, 0.04, darkSteel, 0, 5.0, 0);
  const apexSheaveL = cyl(0.55, 0.55, 0.22, 20, hubSteel, -0.35, 5.0, 0).rotateZ(Math.PI / 2);
  const apexSheaveR = cyl(0.55, 0.55, 0.22, 20, hubSteel, 0.35, 5.0, 0).rotateZ(Math.PI / 2);
  aFramePylonGroup.add(apexHead, apexSheaveL, apexSheaveR);
  turretGroup.add(aFramePylonGroup);

  // Heavy multi-part steel guy cables (ванты)
  const guyCablesGroup = new THREE.Group();
  guyCablesGroup.name = 'GuyCablesGroup';
  const makeCable = (from: THREE.Vector3, to: THREE.Vector3) => {
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    const mesh = cyl(0.045, 0.045, len, 8, ropeMat);
    mesh.position.copy(from).add(to).multiplyScalar(0.5);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
    return mesh;
  };
  const apexL = new THREE.Vector3(-0.35, 8.4, -1.6);
  const apexR = new THREE.Vector3(0.35, 8.4, -1.6);
  const boomHeadL = new THREE.Vector3(-0.6, 6.2, 9.8);
  const boomHeadR = new THREE.Vector3(0.6, 6.2, 9.8);
  guyCablesGroup.add(makeCable(apexL, boomHeadL));
  guyCablesGroup.add(makeCable(apexR, boomHeadR));
  guyCablesGroup.add(makeCable(apexL, boomHeadR));
  guyCablesGroup.add(makeCable(apexR, boomHeadL));
  turretGroup.add(guyCablesGroup);

  // ============================================================
  // 4. BOOM & CROWD SADDLE BLOCK
  // ============================================================
  const boomGroup = new THREE.Group();
  boomGroup.position.set(0, 1.25, 2.4);
  boomGroup.name = 'BoomGroup';

  // Tapered welded box boom extending forward along +Z
  // Base root (пята стрелы)
  const boomRoot = beveledBox(1.8, 1.8, 3.2, 0.06, bodyMat, 0, 0.8, 1.6);
  // Main tapered body
  const boomBody = beveledBox(1.5, 1.4, 4.0, 0.05, bodyMat, 0, 1.1, 4.8);
  // Head section
  const boomHead = beveledBox(1.3, 1.1, 2.8, 0.04, bodyMat, 0, 1.4, 8.0);
  boomGroup.add(boomRoot, boomBody, boomHead);

  // Longitudinal structural flange stiffeners
  for (let i = 0; i < 4; i++) {
    const stiffener = beveledBox(1.65, 0.08, 0.15, 0.02, darkSteel, 0, 0.7 + i * 0.25, 2.0 + i * 1.8);
    boomGroup.add(stiffener);
  }

  // Inspection ladder with rungs along boom right flank
  for (let i = 0; i < 8; i++) {
    const rung = cyl(0.025, 0.025, 0.45, 8, hubSteel, 0.95, 0.2 + i * 0.22, 2.2 + i * 0.8).rotateZ(Math.PI / 2);
    boomGroup.add(rung);
  }

  // Shipper shaft saddle block mechanism (седловой подшипник) at z = 4.4
  const saddleBlock = beveledBox(2.2, 0.9, 1.2, 0.04, bodyMat, 0, 0.5, 4.4);
  const shipperShaft = cyl(0.22, 0.22, 2.6, 16, hubSteel, 0, 0.5, 4.4).rotateZ(Math.PI / 2);
  // Crowd motor housings on both sides
  const crowdMotorL = cyl(0.38, 0.38, 0.9, 16, darkSteel, -1.25, 0.5, 4.4).rotateZ(Math.PI / 2);
  const crowdMotorR = cyl(0.38, 0.38, 0.9, 16, darkSteel, 1.25, 0.5, 4.4).rotateZ(Math.PI / 2);
  boomGroup.add(saddleBlock, shipperShaft, crowdMotorL, crowdMotorR);

  // Twin boom point sheaves (головные блоки Ø1600мм) at z = 8.8
  const boomSheaveL = cyl(0.8, 0.8, 0.28, 24, hubSteel, -0.5, 1.4, 8.8).rotateZ(Math.PI / 2);
  const boomSheaveR = cyl(0.8, 0.8, 0.28, 24, hubSteel, 0.5, 1.4, 8.8).rotateZ(Math.PI / 2);
  const sheaveGuard = beveledBox(1.7, 0.2, 0.35, 0.02, darkSteel, 0, 2.3, 8.8);
  boomGroup.add(boomSheaveL, boomSheaveR, sheaveGuard);

  // High-intensity worklight pods shining forward into muckpile
  boomGroup.add(cyl(0.14, 0.14, 0.25, 12, hubSteel, -0.9, 0.3, 6.2).rotateX(0.4));
  boomGroup.add(cyl(0.14, 0.14, 0.25, 12, hubSteel, 0.9, 0.3, 6.2).rotateX(0.4));

  turretGroup.add(boomGroup);

  // ============================================================
  // 5. DIPPER STICK (РУКОЯТЬ КОВША)
  // ============================================================
  const stickGroup = new THREE.Group();
  stickGroup.position.set(0, -0.4, 6.5);
  stickGroup.name = 'StickGroup';

  // Twin dipper handles sliding through the saddle block
  const handleL = beveledBox(0.38, 0.42, 5.8, 0.03, darkSteel, -0.65, 0, 2.9);
  const handleR = beveledBox(0.38, 0.42, 5.8, 0.03, darkSteel, 0.65, 0, 2.9);
  stickGroup.add(handleL, handleR);

  // Heavy cast crowd rack teeth (зубчатые рейки) welded along bottom
  for (let i = 0; i < 14; i++) {
    const zpos = 0.6 + i * 0.38;
    const rackL = beveledBox(0.36, 0.14, 0.18, 0.01, manganese, -0.65, -0.26, zpos);
    const rackR = beveledBox(0.36, 0.14, 0.18, 0.01, manganese, 0.65, -0.26, zpos);
    stickGroup.add(rackL, rackR);
  }

  // Cross-tie structural box members
  stickGroup.add(beveledBox(1.6, 0.25, 0.25, 0.02, darkSteel, 0, 0, 1.8));
  stickGroup.add(beveledBox(1.6, 0.25, 0.25, 0.02, darkSteel, 0, 0, 4.8));

  // Cast hoist bail yoke (коромысло ковша) with equalizer sheaves
  const bailYoke = beveledBox(1.8, 0.35, 0.42, 0.03, hubSteel, 0, 0.45, 5.4);
  const eqSheaveL = cyl(0.38, 0.38, 0.22, 16, hubSteel, -0.55, 0.72, 5.4).rotateZ(Math.PI / 2);
  const eqSheaveR = cyl(0.38, 0.38, 0.22, 16, hubSteel, 0.55, 0.72, 5.4).rotateZ(Math.PI / 2);
  stickGroup.add(bailYoke, eqSheaveL, eqSheaveR);

  boomGroup.add(stickGroup);

  // ============================================================
  // 6. AUTHENTIC HOLLOW DIPPER (15 m³ WELDED ROCK BUCKET)
  // ============================================================
  const bucketGroup = new THREE.Group();
  bucketGroup.position.set(0, 0, 5.6);
  bucketGroup.name = 'BucketGroup';

  // Hollow U-shaped dipper scoop:
  // Left and Right cheek plates (толстые боковины ковша)
  const cheekL = beveledBox(0.18, 2.2, 2.4, 0.04, bucketSteel, -1.35, -0.9, 0.6);
  const cheekR = beveledBox(0.18, 2.2, 2.4, 0.04, bucketSteel, 1.35, -0.9, 0.6);
  bucketGroup.add(cheekL, cheekR);

  // Curved back wall plate
  const backPlate = beveledBox(2.6, 2.2, 0.22, 0.03, bucketSteel, 0, -0.9, -0.55);
  bucketGroup.add(backPlate);

  // Side wear shrouds (GET wing protectors)
  const shroudL = beveledBox(0.14, 0.65, 1.8, 0.02, manganese, -1.45, -0.85, 0.6);
  const shroudR = beveledBox(0.14, 0.65, 1.8, 0.02, manganese, 1.45, -0.85, 0.6);
  bucketGroup.add(shroudL, shroudR);

  // Heavy cast manganese cutting lip (козырек 110Г13Л)
  const cuttingLip = beveledBox(2.8, 0.32, 0.48, 0.04, manganese, 0, -1.9, 1.85);
  cuttingLip.rotation.x = 0.18;
  bucketGroup.add(cuttingLip);

  // 5 heavy cast chisel digging teeth with rock adapters
  for (let i = 0; i < 5; i++) {
    const tx = -1.1 + i * 0.55;
    // Tooth adapter
    const adapter = beveledBox(0.24, 0.28, 0.35, 0.02, manganese, tx, -1.95, 2.05);
    adapter.rotation.x = 0.22;
    // Chisel tooth point (сталь 110Г13Л)
    const toothPoint = cyl(0.06, 0.14, 0.55, 6, manganese, tx, -2.05, 2.42);
    toothPoint.rotation.x = Math.PI / 2 + 0.22;
    bucketGroup.add(adapter, toothPoint);
  }

  // Hinged tripping bottom door (днище ковша на шарнирах)
  const bucketDoorMesh = beveledBox(2.5, 0.16, 2.3, 0.03, bucketSteel, 0, -2.02, 0.55);
  bucketDoorMesh.name = 'BucketDoor';
  bucketGroup.add(bucketDoorMesh);

  // Ore payload resting INSIDE the hollow dipper bowl
  const bucketOreMesh = new THREE.Mesh(new THREE.DodecahedronGeometry(1.0, 1), oreMat);
  bucketOreMesh.position.set(0, -0.85, 0.55);
  bucketOreMesh.scale.set(1.2, 0.75, 1.1);
  bucketOreMesh.castShadow = true;
  bucketOreMesh.name = 'BucketOre';
  bucketGroup.add(bucketOreMesh);

  // Subtle mineral dust & rock fragmentation chips (Digging sparks)
  const diggingSparksGroup = new THREE.Group();
  diggingSparksGroup.name = 'DiggingSparksGroup';
  const chipMat = new THREE.MeshStandardMaterial({ color: 0xaa8844, roughness: 0.9, emissive: 0x442200, emissiveIntensity: 0.8 });
  for (let i = 0; i < 12; i++) {
    const chip = beveledBox(0.06, 0.06, 0.06, 0.01, chipMat, (Math.random() - 0.5) * 2.2, -1.95 + (Math.random() - 0.5) * 0.3, 2.2 + Math.random() * 0.4);
    diggingSparksGroup.add(chip);
  }
  bucketGroup.add(diggingSparksGroup);

  // Falling ore chunks during truck dump
  const fallingOreGroup = new THREE.Group();
  fallingOreGroup.name = 'FallingOreGroup';
  for (let i = 0; i < 10; i++) {
    const chunk = new THREE.Mesh(new THREE.DodecahedronGeometry(0.18 + Math.random() * 0.12, 0), oreMat);
    chunk.position.set((Math.random() - 0.5) * 1.8, -2.4 - Math.random() * 1.5, 0.6 + (Math.random() - 0.5) * 1.2);
    chunk.castShadow = true;
    fallingOreGroup.add(chunk);
  }
  bucketGroup.add(fallingOreGroup);

  // Dummy claw groups for backward animation compatibility (NO ROBOTIC CLAWS RENDERED!)
  const upperClawGroup = new THREE.Group();
  upperClawGroup.name = 'UpperClawGroup';
  const lowerClawGroup = new THREE.Group();
  lowerClawGroup.name = 'LowerClawGroup';
  bucketGroup.add(upperClawGroup, lowerClawGroup);

  stickGroup.add(bucketGroup);
  root.add(turretGroup);

  shadowAll(root);

  return {
    root,
    turretGroup,
    aFramePylonGroup,
    guyCablesGroup,
    boomGroup,
    stickGroup,
    bucketGroup,
    bucketDoorMesh,
    bucketOreMesh,
    diggingSparksGroup,
    fallingOreGroup,
    upperClawGroup,
    lowerClawGroup,
    hydraulicPistonMeshes: [],
  } as ExcavatorRig;
}

/* ============================================================================
 *  2. CATERPILLAR CAT 6020B HYDRAULIC SHOVEL (224t / 12 m³)
 * ==========================================================================*/

export function createUpgradedCAT6020B(mats: any): ExcavatorRig {
  const root = new THREE.Group();
  root.name = 'EXCAVATOR_CAT6020B';

  const catYellow = safeMat(mats, 'catYellowPaint', new THREE.MeshStandardMaterial({ color: 0xf5b800, metalness: 0.35, roughness: 0.5 }));
  const darkSteel = safeMat(mats, 'belazChassisDark', new THREE.MeshStandardMaterial({ color: 0x222426, metalness: 0.8, roughness: 0.6 }));
  const hubSteel = safeMat(mats, 'wheelHubSteel', new THREE.MeshStandardMaterial({ color: 0x484c52, metalness: 0.85, roughness: 0.45 }));
  const chromeMat = safeMat(mats, 'chromeCylinder', new THREE.MeshStandardMaterial({ color: 0xd8dde3, metalness: 0.98, roughness: 0.12 }));
  const bucketSteel = safeMat(mats, 'weatheredBucketSteel', new THREE.MeshStandardMaterial({ color: 0x423c36, metalness: 0.65, roughness: 0.8 }));
  const manganese = safeMat(mats, 'manganeseToothSteel', new THREE.MeshStandardMaterial({ color: 0x242628, metalness: 0.9, roughness: 0.35 }));
  const glassMat = safeMat(mats, 'cabGlass', safeMat(mats, 'tintedGlass', new THREE.MeshStandardMaterial({ color: 0x1e3344, metalness: 0.2, roughness: 0.08, transparent: true, opacity: 0.5 })));
  const oreMat = safeMat(mats, 'orePayloadMat', new THREE.MeshStandardMaterial({ color: 0x5a4838, roughness: 0.95, metalness: 0.1 }));

  // ============================================================
  // 1. UNDERCARRIAGE
  // ============================================================
  const undercarriage = new THREE.Group();
  undercarriage.name = 'Undercarriage';

  // Ground contact shadow
  const shadowPlane = new THREE.Mesh(new THREE.PlaneGeometry(22, 26), safeMat(mats, 'contactShadowMat', new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.6 })));
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = 0.02;
  shadowPlane.renderOrder = 2;
  root.add(shadowPlane);

  // Heavy crawler tracks with high-drive elevated rear sprockets
  const trackW = 1.35, trackH = 1.55, trackL = 9.2;
  const leftTrack = createCrawlerTrackAssembly(trackW, trackH, trackL, darkSteel, darkSteel, hubSteel, 12);
  leftTrack.position.x = -2.45;
  const rightTrack = createCrawlerTrackAssembly(trackW, trackH, trackL, darkSteel, darkSteel, hubSteel, 12);
  rightTrack.position.x = 2.45;
  undercarriage.add(leftTrack, rightTrack);

  // Heavy carbody center pedestal
  const carbody = beveledBox(3.4, 1.15, 4.8, 0.08, darkSteel, 0, 1.1, 0);
  undercarriage.add(carbody);

  // Slewing bearing ring gear
  const slewRing = cyl(1.85, 1.85, 0.42, 36, hubSteel, 0, 1.75, 0);
  undercarriage.add(slewRing);

  // Diagonal 45° hydraulic boarding stairway at rear-left
  const stair = new THREE.Group();
  stair.position.set(-2.95, 0.1, -3.2);
  for (let i = 0; i < 7; i++) {
    stair.add(beveledBox(0.9, 0.08, 0.32, 0.01, hubSteel, 0, 0.45 + i * 0.26, -0.9 + i * 0.36));
  }
  const railL = cyl(0.04, 0.04, 3.2, 8, catYellow, -0.42, 1.35, 0.2).rotateX(-0.55);
  const railR = cyl(0.04, 0.04, 3.2, 8, catYellow, 0.42, 1.35, 0.2).rotateX(-0.55);
  stair.add(railL, railR);
  undercarriage.add(stair);

  root.add(undercarriage);

  // ============================================================
  // 2. TURRET / REVOLVING DECK & CAT C32 ENGINE HOUSE
  // ============================================================
  const turretGroup = new THREE.Group();
  turretGroup.position.set(0, 1.85, 0);
  turretGroup.name = 'TurretGroup';

  // Revolving deck with perimeter handrails
  const deck = beveledBox(5.6, 0.42, 8.6, 0.06, darkSteel, 0, 0.21, -0.6);
  turretGroup.add(deck);

  // Perimeter yellow safety handrails
  const railPosts = [
    [-2.65, 0.85, 3.4], [2.65, 0.85, 3.4],
    [-2.65, 0.85, -4.6], [2.65, 0.85, -4.6],
    [-2.65, 0.85, -0.6], [2.65, 0.85, -0.6]
  ];
  railPosts.forEach(([x, y, z]) => {
    turretGroup.add(cyl(0.045, 0.045, 0.95, 6, catYellow, x, y, z));
  });
  turretGroup.add(beveledBox(0.06, 0.06, 8.0, 0.01, catYellow, -2.65, 1.35, -0.6));
  turretGroup.add(beveledBox(0.06, 0.06, 8.0, 0.01, catYellow, 2.65, 1.35, -0.6));
  turretGroup.add(beveledBox(5.3, 0.06, 0.06, 0.01, catYellow, 0, 1.35, 3.4));
  turretGroup.add(beveledBox(5.3, 0.06, 0.06, 0.01, catYellow, 0, 1.35, -4.6));

  // Twin Cat C32 ACERT engine housing with beveled corners
  const engineHouse = beveledBox(4.6, 2.1, 4.8, 0.06, catYellow, 0, 1.45, -2.4);
  turretGroup.add(engineHouse);

  // Radiator intake louver banks (black recessed mesh)
  for (let i = 0; i < 6; i++) {
    const lvL = beveledBox(0.06, 0.22, 3.8, 0.01, darkSteel, -2.32, 0.8 + i * 0.24, -2.4);
    const lvR = beveledBox(0.06, 0.22, 3.8, 0.01, darkSteel, 2.32, 0.8 + i * 0.24, -2.4);
    turretGroup.add(lvL, lvR);
  }

  // Twin vertical stainless exhaust mufflers with perforated heat shields
  const muff1 = cyl(0.22, 0.22, 1.6, 16, chromeMat, -1.2, 3.1, -3.2);
  const muff2 = cyl(0.22, 0.22, 1.6, 16, chromeMat, 1.2, 3.1, -3.2);
  const hs1 = cyl(0.32, 0.32, 1.2, 16, darkSteel, -1.2, 3.0, -3.2);
  const hs2 = cyl(0.32, 0.32, 1.2, 16, darkSteel, 1.2, 3.0, -3.2);
  turretGroup.add(muff1, muff2, hs1, hs2);

  // Hydraulic oil cooler fan grill
  const coolerFan = cyl(0.75, 0.75, 0.15, 24, darkSteel, 0, 2.52, -4.6).rotateX(Math.PI / 2);
  turretGroup.add(coolerFan);

  // Massive rear counterweight with bold black/yellow chevron hazard stripes
  const counterweight = beveledBox(5.2, 1.9, 1.6, 0.08, darkSteel, 0, 1.2, -5.2);
  turretGroup.add(counterweight);
  for (let i = 0; i < 8; i++) {
    const stripe = beveledBox(0.32, 1.1, 0.04, 0.01, catYellow, -2.1 + i * 0.6, 1.2, -6.02);
    stripe.rotation.z = 0.52;
    turretGroup.add(stripe);
  }

  // High-mounted FOPS operator cab on front-left (x = -1.8, z = +2.2)
  const cabGroup = new THREE.Group();
  cabGroup.position.set(-1.75, 0.42, 2.2);
  const cabBase = beveledBox(1.8, 0.25, 2.0, 0.03, darkSteel, 0, 0.12, 0);
  const cabBody = beveledBox(1.8, 1.9, 2.0, 0.05, catYellow, 0, 1.15, 0);
  cabGroup.add(cabBase, cabBody);
  // Slanted panoramic glass
  const frontGlass = beveledBox(1.65, 1.45, 0.06, 0.01, glassMat, 0, 1.25, 1.02);
  frontGlass.rotation.x = -0.14;
  cabGroup.add(frontGlass);
  const sideGlassL = beveledBox(0.06, 1.45, 1.7, 0.01, glassMat, -0.92, 1.25, 0);
  const sideGlassR = beveledBox(0.06, 1.45, 1.7, 0.01, glassMat, 0.92, 1.25, 0);
  cabGroup.add(sideGlassL, sideGlassR);
  // FOPS overhead protective roof canopy
  const fopsRoof = beveledBox(2.0, 0.18, 2.2, 0.03, catYellow, 0, 2.15, 0);
  cabGroup.add(fopsRoof);
  // High-lumen LED worklight bar
  const lightBar = beveledBox(1.6, 0.14, 0.2, 0.02, hubSteel, 0, 2.28, 0.95);
  cabGroup.add(lightBar);
  turretGroup.add(cabGroup);

  // Empty compatibility groups
  const aFramePylonGroup = new THREE.Group();
  aFramePylonGroup.name = 'AFramePylonGroup';
  const guyCablesGroup = new THREE.Group();
  guyCablesGroup.name = 'GuyCablesGroup';
  turretGroup.add(aFramePylonGroup, guyCablesGroup);

  // ============================================================
  // 3. CURVED SWAN-NECK MONO-BOOM & HYDRAULICS
  // ============================================================
  const boomGroup = new THREE.Group();
  boomGroup.position.set(0, 1.4, 2.2);
  boomGroup.name = 'BoomGroup';

  // Muscular swan-neck mono-boom with variable profile
  // 1. Root pivot beam extending upward-forward
  const boomRoot = beveledBox(1.5, 1.8, 4.2, 0.06, catYellow, 0, 1.1, 1.9);
  boomRoot.rotation.x = -0.32;
  // 2. Knee arch curving forward-downward
  const boomKnee = beveledBox(1.3, 1.4, 3.8, 0.05, catYellow, 0, 2.5, 4.6);
  boomKnee.rotation.x = 0.22;
  // 3. Nose section tapering to stick pivot
  const boomNose = beveledBox(1.1, 1.1, 2.6, 0.04, catYellow, 0, 1.8, 7.2);
  boomNose.rotation.x = 0.45;
  boomGroup.add(boomRoot, boomKnee, boomNose);

  // Cast boom tip nose brackets and heavy pivot pin
  const tipEarL = beveledBox(0.18, 0.95, 1.6, 0.03, catYellow, -0.58, 1.4, 8.2);
  const tipEarR = beveledBox(0.18, 0.95, 1.6, 0.03, catYellow, 0.58, 1.4, 8.2);
  const pivotPin = cyl(0.18, 0.18, 1.45, 16, hubSteel, 0, 1.4, 8.4).rotateZ(Math.PI / 2);
  boomGroup.add(tipEarL, tipEarR, pivotPin);

  // High-pressure steel hydraulic manifold hardlines along top spine
  const hardlineL = cyl(0.08, 0.08, 6.2, 10, hubSteel, 0.52, 2.2, 4.2).rotateX(0.15);
  const hardlineR = cyl(0.08, 0.08, 6.2, 10, hubSteel, -0.52, 2.2, 4.2).rotateX(0.15);
  boomGroup.add(hardlineL, hardlineR);

  // Dual boom hoist cylinders (connecting deck to boom knee)
  const hydraulicPistonMeshes: THREE.Mesh[] = [];
  for (const sx of [-0.92, 0.92]) {
    const barrel = cyl(0.24, 0.24, 2.6, 16, catYellow, sx, 0.4, 1.2).rotateX(-0.35);
    const rod = cyl(0.14, 0.14, 2.4, 16, chromeMat, sx, 1.2, 2.8).rotateX(-0.35);
    boomGroup.add(barrel, rod);
    hydraulicPistonMeshes.push(rod);
  }

  // Stick crowd cylinder on top of boom
  const stickCylBarrel = cyl(0.22, 0.22, 2.4, 16, catYellow, 0, 2.9, 3.8).rotateX(0.28);
  const stickCylRod = cyl(0.13, 0.13, 2.2, 16, chromeMat, 0, 3.5, 5.4).rotateX(0.28);
  boomGroup.add(stickCylBarrel, stickCylRod);
  hydraulicPistonMeshes.push(stickCylRod);

  // Armored hydraulic hose loops (РВД) spanning joints
  for (let i = 0; i < 4; i++) {
    const hose = new THREE.Mesh(new THREE.TorusGeometry(0.32, 0.05, 6, 16, Math.PI), darkSteel);
    hose.position.set(0.68, 1.4 + i * 0.12, 7.4 + (i - 1.5) * 0.25);
    hose.rotation.y = Math.PI / 2;
    boomGroup.add(hose);
  }

  turretGroup.add(boomGroup);

  // ============================================================
  // 4. STICK (РУКОЯТЬ)
  // ============================================================
  const stickGroup = new THREE.Group();
  stickGroup.position.set(0, 1.4, 8.4);
  stickGroup.name = 'StickGroup';

  // Tapered box stick extending forward along +Z
  const stickMain = beveledBox(1.05, 1.2, 5.2, 0.05, catYellow, 0, 0, 2.6);
  // Bottom & side wear plates
  const bottomWear = beveledBox(1.15, 0.12, 4.8, 0.02, darkSteel, 0, -0.65, 2.6);
  const sideWearL = beveledBox(0.12, 1.1, 4.8, 0.02, darkSteel, -0.56, 0, 2.6);
  const sideWearR = beveledBox(0.12, 1.1, 4.8, 0.02, darkSteel, 0.56, 0, 2.6);
  stickGroup.add(stickMain, bottomWear, sideWearL, sideWearR);

  // Dual bucket curl cylinders on stick
  for (const sx of [-0.62, 0.62]) {
    const bCyl = cyl(0.18, 0.18, 1.8, 14, catYellow, sx, 0.72, 1.8).rotateX(Math.PI / 2);
    const rCyl = cyl(0.11, 0.11, 1.6, 14, chromeMat, sx, 0.72, 3.2).rotateX(Math.PI / 2);
    stickGroup.add(bCyl, rCyl);
    hydraulicPistonMeshes.push(rCyl);
  }

  boomGroup.add(stickGroup);

  // ============================================================
  // 5. SCULPTED 12 m³ FRONT-SHOVEL ROCK BUCKET
  // ============================================================
  const bucketGroup = new THREE.Group();
  bucketGroup.position.set(0, 0, 5.2);
  bucketGroup.name = 'BucketGroup';

  // Hollow bucket body: left and right cheek plates
  const cheekL = beveledBox(0.16, 2.1, 2.3, 0.04, bucketSteel, -1.35, -0.85, 0.9);
  const cheekR = beveledBox(0.16, 2.1, 2.3, 0.04, bucketSteel, 1.35, -0.85, 0.9);
  // Backwall frame
  const backwall = beveledBox(2.6, 2.1, 0.35, 0.04, darkSteel, 0, -0.85, -0.15);
  bucketGroup.add(cheekL, cheekR, backwall);

  // GET side shrouds
  const shroudL = beveledBox(0.12, 0.65, 1.8, 0.02, manganese, -1.45, -0.85, 1.0);
  const shroudR = beveledBox(0.12, 0.65, 1.8, 0.02, manganese, 1.45, -0.85, 1.0);
  bucketGroup.add(shroudL, shroudR);

  // Flared manganese cutting lip (козырек)
  const lip = beveledBox(2.8, 0.28, 0.45, 0.03, manganese, 0, -1.85, 2.0);
  lip.rotation.x = 0.22;
  bucketGroup.add(lip);

  // 6 chisel digging teeth (110Г13Л)
  for (let i = 0; i < 6; i++) {
    const tx = -1.15 + i * 0.46;
    const adapter = beveledBox(0.22, 0.24, 0.32, 0.02, manganese, tx, -1.92, 2.18);
    adapter.rotation.x = 0.25;
    const tooth = cyl(0.05, 0.12, 0.52, 6, manganese, tx, -2.02, 2.52);
    tooth.rotation.x = Math.PI / 2 + 0.25;
    bucketGroup.add(adapter, tooth);
  }

  // Clam discharge door / bottom push-plate
  const bucketDoorMesh = beveledBox(2.5, 0.15, 2.0, 0.03, bucketSteel, 0, -1.82, 0.9);
  bucketDoorMesh.name = 'BucketDoor';
  bucketGroup.add(bucketDoorMesh);

  // Heaped ore payload INSIDE the bucket bowl
  const bucketOreMesh = new THREE.Mesh(new THREE.DodecahedronGeometry(1.0, 1), oreMat);
  bucketOreMesh.position.set(0, -0.85, 0.9);
  bucketOreMesh.scale.set(1.2, 0.75, 1.05);
  bucketOreMesh.castShadow = true;
  bucketOreMesh.name = 'BucketOre';
  bucketGroup.add(bucketOreMesh);

  // Subtle mineral dust & chips
  const diggingSparksGroup = new THREE.Group();
  diggingSparksGroup.name = 'DiggingSparksGroup';
  const sparkMat = new THREE.MeshBasicMaterial({ color: 0xffbb33 });
  for (let i = 0; i < 10; i++) {
    const sp = beveledBox(0.05, 0.05, 0.05, 0.01, sparkMat, (Math.random() - 0.5) * 2.2, -1.95 + (Math.random() - 0.5) * 0.3, 2.3 + Math.random() * 0.4);
    diggingSparksGroup.add(sp);
  }
  bucketGroup.add(diggingSparksGroup);

  // Falling ore chunks
  const fallingOreGroup = new THREE.Group();
  fallingOreGroup.name = 'FallingOreGroup';
  for (let i = 0; i < 8; i++) {
    const chunk = new THREE.Mesh(new THREE.DodecahedronGeometry(0.16 + Math.random() * 0.1, 0), oreMat);
    chunk.position.set((Math.random() - 0.5) * 1.6, -2.4 - Math.random() * 1.4, 0.9 + (Math.random() - 0.5) * 1.0);
    chunk.castShadow = true;
    fallingOreGroup.add(chunk);
  }
  bucketGroup.add(fallingOreGroup);

  // Dummy claw groups for animation compatibility (NO ROBOTIC CLAWS RENDERED!)
  const upperClawGroup = new THREE.Group();
  upperClawGroup.name = 'UpperClawGroup';
  const lowerClawGroup = new THREE.Group();
  lowerClawGroup.name = 'LowerClawGroup';
  bucketGroup.add(upperClawGroup, lowerClawGroup);

  stickGroup.add(bucketGroup);
  root.add(turretGroup);

  shadowAll(root);

  return {
    root,
    turretGroup,
    aFramePylonGroup,
    guyCablesGroup,
    boomGroup,
    stickGroup,
    bucketGroup,
    bucketDoorMesh,
    bucketOreMesh,
    diggingSparksGroup,
    fallingOreGroup,
    upperClawGroup,
    lowerClawGroup,
    hydraulicPistonMeshes,
  } as ExcavatorRig;
}
